-- Moni Plus billing with Mercado Pago Subscriptions (contract: without-plan-pending).
--
-- Moni Plus can now be paid for. The Edge Functions `plus-subscription` (user actions) and `mp-webhook` (Mercado Pago
-- notifications) are the only writers; both talk to the database with the service role. Nothing here is callable by
-- a browser: the money-touching functions are granted to service_role ONLY.
--
--   * public.plus_subscriptions: one row per subscription attempt of a user. `external_reference` is a random uuid
--     generated by the server, sent to Mercado Pago and used to reconcile notifications; `preapproval_id` is the
--     Mercado Pago subscription id, stored once Mercado Pago returns it. Clients can only SELECT their own rows.
--   * public.plus_payments: one row per approved Mercado Pago payment already credited. Its primary key is the
--     webhook idempotency key: the same payment arriving twice (Mercado Pago retries) is credited once.
--   * public.start_plus_subscription(): creates the pending row under a per-user lock, refusing a user that already
--     has an authorized subscription ('already_subscribed') or created one in the last 60 seconds
--     ('create_throttled'). Abuse guard + duplicate guard without a race.
--   * public.grant_plus_from_payment(): credits ONE month of Plus for ONE approved payment. Idempotent.
--     expires_at = greatest(now(), current expires_at) + 1 month, so paying early never loses time and a lapsed
--     user starts from now. Returns the new expiry, or NULL when the payment was already credited.
--   * public.set_plus_subscription_status(): syncs the subscription status (and stores preapproval_id). A
--     'cancelled' subscription never goes back (Mercado Pago cancellation is final), so a stale notification
--     cannot reopen it.
--
-- The entitlement itself still lives in public.plus_entitlements (see 20261106000000_moni_plus.sql): is_plus() and
-- my_plus_status() keep working unchanged. Cancelling a subscription does NOT touch the entitlement: Plus runs until
-- the already-paid expiry. There is no refund or proration logic.
--
-- Wrapped in one transaction. Apply AFTER 20261106000000_moni_plus.sql.
-- Rollback:
--   drop function public.set_plus_subscription_status(uuid, text, text),
--     public.grant_plus_from_payment(uuid, text, uuid, numeric),
--     public.start_plus_subscription(uuid, text);
--   drop table public.plus_payments, public.plus_subscriptions;
-- (entitlements already granted from payments stay in plus_entitlements until they expire.)

begin;

-- Tables -------------------------------------------------------------------------------------------

create table public.plus_subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  -- Random, unguessable, generated server-side. Mercado Pago echoes it back, so notifications can be matched.
  external_reference text not null unique check (char_length(external_reference) between 16 and 100),
  -- Mercado Pago subscription (preapproval) id. NULL until Mercado Pago answers the creation call.
  preapproval_id text unique check (preapproval_id is null or char_length(preapproval_id) between 1 and 100),
  status text not null default 'pending' check (status in ('pending', 'authorized', 'paused', 'cancelled')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index plus_subscriptions_user_idx on public.plus_subscriptions (user_id, created_at desc);

-- One row per credited payment. payment_id is the Mercado Pago payment id (text: never parsed as a number).
create table public.plus_payments (
  payment_id text primary key check (char_length(payment_id) between 1 and 100),
  user_id uuid not null references auth.users (id) on delete cascade,
  subscription_id uuid not null references public.plus_subscriptions (id) on delete cascade,
  amount numeric(14, 2) not null check (amount > 0),
  created_at timestamptz not null default now()
);

create index plus_payments_user_idx on public.plus_payments (user_id, created_at desc);

alter table public.plus_subscriptions enable row level security;
alter table public.plus_payments enable row level security;

revoke all on table public.plus_subscriptions, public.plus_payments from public, anon, authenticated;

-- Clients read their own rows only. No INSERT / UPDATE / DELETE grant exists for them.
grant select on table public.plus_subscriptions, public.plus_payments to authenticated;
-- The Edge Functions (service role) read; every write goes through the SECURITY DEFINER functions below.
grant select on table public.plus_subscriptions, public.plus_payments to service_role;

create policy "plus_subscriptions_select_own" on public.plus_subscriptions
for select to authenticated using (user_id = (select auth.uid()));

create policy "plus_payments_select_own" on public.plus_payments
for select to authenticated using (user_id = (select auth.uid()));

-- Start ---------------------------------------------------------------------------------------------

-- Creates the pending row for a new checkout. Raises 'already_subscribed' (54000) when the user has an authorized
-- subscription and 'create_throttled' (54000) when they created one in the last 60 seconds. Returns the row id.
create or replace function public.start_plus_subscription(p_user uuid, p_external_reference text)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if p_user is null then
    raise exception 'invalid_user' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('plus_sub:' || p_user::text, 0));

  if exists (
    select 1 from public.plus_subscriptions s where s.user_id = p_user and s.status = 'authorized'
  ) then
    raise exception 'already_subscribed' using errcode = '54000';
  end if;

  if exists (
    select 1 from public.plus_subscriptions s
    where s.user_id = p_user and s.status = 'pending' and s.created_at > now() - interval '60 seconds'
  ) then
    raise exception 'create_throttled' using errcode = '54000';
  end if;

  insert into public.plus_subscriptions (user_id, external_reference)
  values (p_user, p_external_reference)
  returning id into v_id;

  return v_id;
end;
$$;

-- Credit ---------------------------------------------------------------------------------------------

-- Credits one month of Plus for one approved payment. Returns the new expiry, or NULL when p_payment_id was already
-- credited (replayed notification). The insert into plus_payments is the idempotency gate: only the call that
-- inserted the row touches plus_entitlements, and a concurrent duplicate waits on the primary key and then no-ops.
create or replace function public.grant_plus_from_payment(
  p_user uuid,
  p_payment_id text,
  p_subscription uuid,
  p_amount numeric
)
returns timestamptz
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_rows int;
  v_expires timestamptz;
begin
  if p_user is null or p_payment_id is null or p_subscription is null or p_amount is null or p_amount <= 0 then
    raise exception 'invalid_payment' using errcode = '22023';
  end if;

  -- The subscription must belong to the user being credited.
  if not exists (
    select 1 from public.plus_subscriptions s where s.id = p_subscription and s.user_id = p_user
  ) then
    raise exception 'subscription_not_found' using errcode = 'P0002';
  end if;

  insert into public.plus_payments (payment_id, user_id, subscription_id, amount)
  values (p_payment_id, p_user, p_subscription, round(p_amount, 2))
  on conflict (payment_id) do nothing;
  get diagnostics v_rows = row_count;

  if v_rows = 0 then
    return null;
  end if;

  insert into public.plus_entitlements as e (user_id, source, granted_at, expires_at)
  values (p_user, 'mercadopago', now(), now() + interval '1 month')
  on conflict (user_id) do update
    set source = 'mercadopago',
        granted_at = now(),
        expires_at = greatest(now(), coalesce(e.expires_at, now())) + interval '1 month'
  returning e.expires_at into v_expires;

  return v_expires;
end;
$$;

-- Status sync ------------------------------------------------------------------------------------------

-- Updates the status of a subscription and, when given, stores its Mercado Pago id (only if still unset).
-- 'cancelled' is terminal. Returns false when the subscription does not exist.
create or replace function public.set_plus_subscription_status(
  p_subscription uuid,
  p_status text,
  p_preapproval_id text default null
)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_rows int;
begin
  if p_status is null or p_status not in ('pending', 'authorized', 'paused', 'cancelled') then
    raise exception 'invalid_status' using errcode = '22023';
  end if;

  update public.plus_subscriptions s
  set status = case when s.status = 'cancelled' then s.status else p_status end,
      preapproval_id = coalesce(s.preapproval_id, p_preapproval_id),
      updated_at = now()
  where s.id = p_subscription;
  get diagnostics v_rows = row_count;

  return v_rows > 0;
end;
$$;

-- Grants ---------------------------------------------------------------------------------------------

-- Money-touching functions: service_role ONLY. Revoking from PUBLIC matters because functions are executable by
-- PUBLIC by default; anon / authenticated are revoked explicitly as well (Supabase default privileges grant them).
revoke execute on function
  public.start_plus_subscription(uuid, text),
  public.grant_plus_from_payment(uuid, text, uuid, numeric),
  public.set_plus_subscription_status(uuid, text, text)
from public, anon, authenticated;
grant execute on function
  public.start_plus_subscription(uuid, text),
  public.grant_plus_from_payment(uuid, text, uuid, numeric),
  public.set_plus_subscription_status(uuid, text, text)
to service_role;

commit;
